import 'package:flutter/foundation.dart';
import 'package:lottie/lottie.dart';

/// Every Lottie animation bundled with the app. Use these constants instead of path strings:
/// a typo then fails to compile, and the preload and the asset test cover the whole list.
///
/// `trophyShine` and `giftSparkles` are generated by `tool/lottie/generate.py`.
abstract final class SiphoLotties {
  static const confetti = 'assets/animations/confetti_celebration.json';
  static const scanLaser = 'assets/animations/scan_laser.json';
  static const streakFire = 'assets/animations/streak_fire.json';
  static const xpCoins = 'assets/animations/xp_coins.json';
  static const trophyShine = 'assets/animations/trophy_shine.json';
  static const giftSparkles = 'assets/animations/gift_sparkles.json';

  static const all = <String>[
    confetti,
    scanLaser,
    streakFire,
    xpCoins,
    trophyShine,
    giftSparkles,
  ];
}

/// Parses every animation once so the first time a screen shows one it does not stutter
/// (the `lottie` package caches the parsed composition). A broken file is logged, never fatal.
Future<void> preloadSiphoLotties() async {
  await Future.wait(
    SiphoLotties.all.map((path) async {
      try {
        await AssetLottie(path).load();
      } catch (error) {
        debugPrint('[Lottie] could not preload $path: $error');
      }
    }),
  );
}
